import React, { useState, useEffect, useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';
// 1. Remove 'useHistory' and keep 'useParams' and 'useNavigate'
import { useParams, useNavigate } from 'react-router-dom';
import { GLOBALTYPES } from '../../redux/actions/globalTypes';
import { addUser, getConversations } from "../../redux/actions/messageAction";
import { getDataAPI } from '../../utils/fetchData';
import UserCard from "../UserCard";

const LeftSide = () => {
    const { auth, message } = useSelector((state) => state);
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const { id } = useParams();
    const pageEnd = useRef();
    const [page, setPage] = useState(0);

    const [search, setSearch] = useState('');
    const [searchUsers, setSearchUsers] = useState([]);

    const handleSearch = async e => {
        e.preventDefault();
        if (!search) return setSearchUsers([]);

        try {
            const res = await getDataAPI(`search?username=${search}`, auth.token);
            setSearchUsers(res.data.users);
        } catch (err) {
            dispatch({
                type: GLOBALTYPES.ALERT,
                payload: { error: err.response.data.msg },
            });
        }
    };

    const handleAddUser = (user) => {
        setSearch('');
        setSearchUsers([]);
        // 2. Correct the payload for the addUser action
        dispatch(addUser({ ...user, text: '', media: [] }, message.users));
        // 3. Use the 'navigate' function for redirection
        return navigate(`/message/${user._id}`);
    };

    const isActive = (user) => {
        if (id === user._id) return 'active';
        return '';
    }

    useEffect(() => {
        if (message.firstLoad) return;
        dispatch(getConversations({ auth }));
    }, [dispatch, auth, message.firstLoad]);

    useEffect(() => {
        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0].isIntersecting) {
                    setPage((p) => p + 1);
                }
            },
            {
                threshold: 0.1,
            }
        );
        if (pageEnd.current) {
            observer.observe(pageEnd.current);
        }
        return () => {
            if (pageEnd.current) {
                observer.unobserve(pageEnd.current);
            }
        }
    }, [setPage]);

    useEffect(() => {
        if (message.resultUsers >= (page - 1) * 9 && page > 1) {
            dispatch(getConversations({ auth, page }));
        }
    }, [message.resultUsers, page, auth, dispatch]);

    return (
        <>
            <form className="message_header" onSubmit={handleSearch}>
                <input
                    type="text"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    placeholder="search..."
                />
                <button style={{ display: "none" }} type="submit" id="search">
                    Search
                </button>
            </form>

            <div className="message_chat_list">
                {searchUsers.length !== 0 ? (
                    <>
                        {searchUsers.map((user) => (
                            <div
                                key={user._id}
                                className={`message_user ${isActive(user)}`}
                                onClick={() => handleAddUser(user)}
                            >
                                <UserCard user={user} />
                            </div>
                        ))}
                    </>
                ) : (
                    <>
                        {message.users.map((user) => (
                            <div
                                key={user._id}
                                // 4. Corrected typo from 'cclassName' to 'className'
                                className={`message_user ${isActive(user)}`}
                                onClick={() => handleAddUser(user)}
                            >
                                <UserCard user={user} msg={true}>
                                    <i className="fas fa-circle" />
                                </UserCard>
                            </div>
                        ))}
                    </>
                )}
                <button style={{ opacity: 0 }} ref={pageEnd}>Load more..</button>
            </div>
        </>
    );
}

export default LeftSide;
